<script setup lang="ts">
/**
 * Markdown.Blocks: a reply’s blocks, each as the member that draws its kind.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { inlineText, markdownHeadingLevel, type MarkdownBlock } from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import CodeBlock from '../structure/CodeBlock.vue'
import Heading from '../structure/Heading.vue'
import MarkdownInlines from './MarkdownInlines.vue'
import Separator from '../structure/Separator.vue'
import Table from '../structure/Table.vue'
import TableBody from '../structure/TableBody.vue'
import TableCell from '../structure/TableCell.vue'
import TableHead from '../structure/TableHead.vue'
import TableHeader from '../structure/TableHeader.vue'
import TableRow from '../structure/TableRow.vue'
import Text from '../structure/Text.vue'
import type { CitationSource } from './SourceList.vue'

export interface MarkdownBlocksProps {
  blocks: MarkdownBlock[]
  size: 'sm' | 'md'
  sources: CitationSource[]
  /**
   * The shallowest heading depth in the reply, which is level 2.
   */
  shallowest: number
  /**
   * Whether the caret ends the last block.
   */
  caret: boolean
}

defineOptions({ name: 'MarkdownBlocks', inheritAttrs: false })

defineProps<MarkdownBlocksProps>()
</script>

<template>
  <template v-for="(block, index) in blocks" :key="index">
    <Text v-if="block.kind === 'paragraph'" :size="size">
      <MarkdownInlines :nodes="block.children" :sources="sources" />
      <!-- caret -->
      <span v-if="caret && index === blocks.length - 1" :class="styles.caret" aria-hidden="true" />
    </Text>
    <Heading
      v-else-if="block.kind === 'heading'"
      :level="markdownHeadingLevel(block.depth, shallowest)"
    >
      {{ inlineText(block.children) }}
    </Heading>
    <CodeBlock v-else-if="block.kind === 'code'" :copyable="block.closed">
      {{ block.text }}
    </CodeBlock>
    <!-- quote -->
    <blockquote v-else-if="block.kind === 'quote'" :class="styles.quote">
      <MarkdownBlocks
        :blocks="block.children"
        :size="size"
        :sources="sources"
        :shallowest="shallowest"
        :caret="caret && index === blocks.length - 1"
      />
    </blockquote>
    <!-- list -->
    <component
      v-else-if="block.kind === 'list'"
      :is="block.ordered ? 'ol' : 'ul'"
      :class="styles.list"
      :start="block.ordered && block.start !== 1 ? block.start : undefined"
    >
      <template v-for="(item, position) in block.items" :key="position">
        <!-- item -->
        <li :class="styles.item">
          <MarkdownBlocks
            :blocks="item"
            :size="size"
            :sources="sources"
            :shallowest="shallowest"
            :caret="caret && index === blocks.length - 1 && position === block.items.length - 1"
          />
        </li>
      </template>
    </component>
    <Table v-else-if="block.kind === 'table'">
      <TableHead>
        <TableRow>
          <template v-for="(head, column) in block.header" :key="column">
            <TableHeader :numeric="block.align[column] === 'end'">
              <MarkdownInlines :nodes="head" :sources="sources" />
            </TableHeader>
          </template>
        </TableRow>
      </TableHead>
      <TableBody>
        <template v-for="(row, line) in block.rows" :key="line">
          <TableRow>
            <template v-for="(value, column) in row" :key="column">
              <TableCell :numeric="block.align[column] === 'end'">
                <MarkdownInlines :nodes="value" :sources="sources" />
              </TableCell>
            </template>
          </TableRow>
        </template>
      </TableBody>
    </Table>
    <Separator v-else-if="block.kind === 'rule'" />
  </template>
</template>
